#include <bits/stdc++.h>
using namespace std; using U=__uint128_t; using I=unsigned long long;
using Table=array<int,12>;
int ctz(U x){I l=x;return l?__builtin_ctzll(l):64+__builtin_ctzll(I(x>>64));}
string show(const Table&p){string s;for(int j=0;j<12;j++){if(j&&j%2==0)s+='_';int a=p[j];if(a<0)s+="---";else{s+='0'+a/12;s+=a%12>=6?'R':'L';s+='A'+a%6;}}return s;}
Table parse(string s){s.erase(remove(s.begin(),s.end(),'_'),s.end());Table p;for(int i=0;i<12;i++){auto a=s.substr(3*i,3);p[i]=a=="---"?-1:(a[0]-'0')*12+(a[1]=='R'?6:0)+a[2]-'A';}return p;}
struct DFA {string code;int rev,d,N,H;vector<int>D;vector<array<int,2>>inv[24];DFA(string s):code(s),rev(s[0]-'0'),d((s.size()-1)/2),N(6*d+1),H(N-1){if(d>20)abort();for(size_t j=1;j<s.size();j++){int x=s[j]<='9'?s[j]-'0':s[j]-'a'+10;if(x<0||x>=d)abort();D.push_back(x);inv[x].push_back({int(j-1)/2,int(j-1)%2});}}};
bool far(const Table&p,const DFA&c){U T[256]={};struct Rule{int dst,src,off;};Rule rules[1600];int rn=0,N=c.N,H=c.H;U halt=U(1)<<H;T[H]=T[N+H]=halt;for(int l=0;l<c.d;l++)for(int q=0;q<6;q++)for(int a=0;a<2;a++){int mv=p[q*2+a],dst=a*N+6*l+q;if(mv<0){T[dst]=halt;continue;}int w=mv>=12,r=mv%12>=6,nxt=mv%6;if(r!=c.rev)T[dst]=U(1)<<(6*c.D[2*l+w]+nxt);else for(auto [j,b]:c.inv[l])rules[rn++]={dst,b*N+6*j+nxt,w*N};}for(;;){U z=halt,old;do{old=z;for(int j=0;j<N;j++)if(T[j]&z)z|=U(1)<<j;if(z&1)return false;}while(z!=old);bool ch=false;for(int i=0;i<rn;i++){auto [dst,src,off]=rules[i];U v=T[dst],b=T[src];while(b){int k=ctz(b);v|=T[off+k];b&=b-1;}if(v!=T[dst]){T[dst]=v;ch=true;}}if(!ch)return true;}}
struct Result{int tag,n,s;bool right=false;int bound=0;};
// All emitted cycles and FAR certificates are independently checked in Lean.
template<int L,int P> struct Classifier{static constexpr int O=L+2,W=(2*L+5+63)/64;using Bits=array<I,W>;Bits hist[L+1],t;int heads[L+1],prev[6][L+1],cnt[6];
I slice(const Bits&a,int x){int i=x/64,k=x%64;if(x<0){if(x<=-64)return 0;return a[0]<<(-x);}if(i>=W)return 0;return (a[i]>>k)|(k&&i+1<W?a[i+1]<<(64-k):0);}
bool eq(const Bits&a,const Bits&b,int shift,int lo,int hi){for(int x=lo;x<=hi;x+=64){I mask=hi-x>=63?~I(0):(I(1)<<(hi-x+1))-1;if(((slice(a,x)^slice(b,x+shift))&mask)!=0)return false;}return true;}
Result run(const Table&p){t.fill(0);fill(cnt,cnt+6,0);int q=0,h=O;int lowAll=h,highAll=h;for(int n=0;n<=L;n++){int s=q*2+((t[h/64]>>(h%64))&1);if(p[s]<0)return {0,n,s};int low=h,high=h,i=n-1;for(int k=cnt[q]-1;k>=0;k--){int j=prev[q][k];if(n-j>P)break;while(i>=j){low=min(low,heads[i]);high=max(high,heads[i]);--i;}int d=h-heads[j];if(d>=0&&eq(hist[j],t,d,low,highAll))return {1,j,n-j,true,low-O};if(d<=0&&eq(hist[j],t,d,lowAll,high))return {1,j,n-j,false,high-O};}hist[n]=t;heads[n]=h;prev[q][cnt[q]++]=n;int a=p[s];I mask=I(1)<<(h%64);if(a>=12)t[h/64]|=mask;else t[h/64]&=~mask;h+=a%12>=6?1:-1;lowAll=min(lowAll,h);highAll=max(highAll,h);q=a%6;}return {2,L,0};}};
Classifier<160,80> shortC;Classifier<2000,256> longC;
vector<DFA> bank;Table p;I nodes=0,sp=0,cy=0,fa=0,la=0,op=0,ha=0,mhalt=0,mnon=0,mopen=0;int score=0;I pow25[13];vector<string>opens;unordered_map<string,int>used;
ostream *tree=nullptr;
void walk(int c,I mult,int holes){++nodes;auto a=shortC.run(p);if(a.tag==2){for(auto &df:bank)if(far(p,df)){fa++;mnon+=mult*pow25[holes];used[df.code]++;if(tree)*tree<<"[\"far\",\""<<df.code<<"\"]";return;}a=longC.run(p);}if(a.tag==1){cy++;mnon+=mult*pow25[holes];if(tree)*tree<<"[\"cycle\","<<a.n<<","<<a.s<<","<<(a.right?"true":"false")<<","<<a.bound<<"]";return;}if(a.tag==2){op++;mopen+=mult*pow25[holes];opens.push_back(show(p));if(tree)*tree<<"[\"open\",\""<<show(p)<<"\"]";return;}int n=a.n,s=a.s;if(!(holes&&p[s]<0&&s/2<c))abort();ha++;score=max(score,n+6);mhalt+=mult*pow25[holes-1];if(holes==1){la++;mnon+=24*mult;if(tree)*tree<<"[\"last\","<<n<<","<<s<<"]";return;}sp++;if(tree)*tree<<"[\"split\","<<n<<","<<s<<",[";for(int mv=0;mv<24;mv++){if(tree&&mv)*tree<<",";int q=mv%6;if(q>c){if(tree)*tree<<"[\"skip\"]";continue;}p[s]=mv;walk(max(c,q+1),mult*(q==c?6-c:1),holes-1);}p[s]=-1;if(tree)*tree<<"]]";}
int main(int argc,char**argv){if(argc!=4&&argc!=5)return 1;ofstream tf;if(argc==5){tf.open(argv[4]);tree=&tf;}p=parse(argv[1]);int c=atoi(argv[2]);ifstream f(argv[3]);string s;unordered_set<string>seen;while(f>>s)if(seen.insert(s).second)bank.emplace_back(s);int holes=count(p.begin(),p.end(),-1);pow25[0]=1;for(int i=1;i<13;i++)pow25[i]=25*pow25[i-1];walk(c,1,holes);if(mhalt+mnon+mopen!=pow25[holes])abort();cout<<"{\"parent\":\""<<show(p)<<"\",\"cut\":"<<c<<",\"stats\":{\"nodes\":"<<nodes<<",\"split\":"<<sp<<",\"cycle\":"<<cy<<",\"far\":"<<fa<<",\"last\":"<<la<<",\"open\":"<<op<<",\"halt\":"<<ha<<",\"score\":"<<score<<"},\"mass\":{\"halt\":\""<<mhalt<<"\",\"nonhalt\":\""<<mnon<<"\",\"open\":\""<<mopen<<"\"},\"opens\":[";for(size_t i=0;i<opens.size();i++){if(i)cout<<',';cout<<'"'<<opens[i]<<'"';}cout<<"]}\n";}
